WHERE ce.MEM_CODE = #{memCode}
  AND c.DELETE_YN = 0


    AND ce.STATUS = #{status}



    AND c.TITLE LIKE CONCAT('%', #{keyword}, '%')

mapper.select:


SELECT


FROM ranked_members r
WHERE r.code = #{memberCode}

SELECT
FROM ranked_members r
ORDER BY r.rating_score DESC, r.code ASC LIMIT #{offset}, #{perPage}

SELECT c.CODE AS code, c.FEED_CODE AS feedCode, c.CONTENT AS content, f.TITLE AS feedTitle, DATE_FORMAT(c.CREATED_AT, '%Y-%m-%d %H:%i:%s') AS createdAt
FROM COMMENTS c JOIN FEED f ON f.CODE = c.FEED_CODE
ORDER BY c.CREATED_AT DESC, c.CODE DESC LIMIT #{offset}, #{perPage}
